 * intl-fmt — tiny i18n number & date helpers built on the Intl APIs.
 * Bundler-free ESM, zero dependencies.
 */

/** Split an integer amount of cents into whole + fractional parts. */
function splitCents(cents) {
  const negative = cents < 0;
  const abs = Math.abs(Math.round(cents));
  return {
    sign: negative ? -1 : 1,
    units: Math.floor(abs / 100),
    frac: abs % 100,
  };
}

/**
 * Format a money amount given in cents, e.g. formatMoney(123456, "EUR", "de-DE")
 * -> "1.234,56 €".
 */
export function formatMoney(cents, currency, locale) {
  const { sign, units, frac } = splitCents(cents);
  const formatter = new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  // Compose from absolute value so rounding of sub-cent inputs is predictable.
  const value = sign * (units + frac / 100);
  return formatter.format(value);
}

const COMPACT_THRESHOLDS = [
  { divisor: 1e12, suffixKey: "T" },
  { divisor: 1e9, suffixKey: "G" },
  { divisor: 1e6, suffixKey: "M" },
  { divisor: 1e3, suffixKey: "K" },
];

/**
 * Compact number formatting, e.g. formatCompact(1500000, "en-US") -> "1.5M",
 * formatCompact(1500000, "de-DE") -> "1,5 Mio.".
 */
export function formatCompact(n, locale) {
  const abs = Math.abs(n);
  if (abs >= 1000) {
    const formatter = new Intl.NumberFormat(locale, {
      notation: "compact",
      compactDisplay: "short",
      maximumFractionDigits: 1,
    });
    return formatter.format(n);
  }
  return new Intl.NumberFormat(locale).format(n);
}

const RELATIVE_UNITS = [
  { unit: "year", ms: 365.25 * 24 * 60 * 60 * 1000 },
  { unit: "month", ms: 30.44 * 24 * 60 * 60 * 1000 },
  { unit: "week", ms: 7 * 24 * 60 * 60 * 1000 },
  { unit: "day", ms: 24 * 60 * 60 * 1000 },
  { unit: "hour", ms: 60 * 60 * 1000 },
  { unit: "minute", ms: 60 * 1000 },
  { unit: "second", ms: 1000 },
];

/**
 * Relative time like "3 days ago" / "vor 3 Tagen". Picks the largest unit
 * whose magnitude is >= 1, falling back to seconds for very recent times.
 */
export function timeAgo(fromMs, nowMs = Date.now(), locale = "en-US") {
  const diffMs = nowMs - fromMs;
  const past = diffMs >= 0;
  const absDiff = Math.abs(diffMs);

  let chosen = RELATIVE_UNITS[RELATIVE_UNITS.length - 1];
  for (const candidate of RELATIVE_UNITS) {
    if (absDiff >= candidate.ms) {
      chosen = candidate;
      break;
    }
  }

  const value = Math.round(absDiff / chosen.ms);
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "always" });
  return rtf.format(past ? -value : value, chosen.unit);
}
