import assert from "node:assert/strict";
import { formatMoney, formatCompact, timeAgo } from "./index.mjs";

test("formatMoney formats USD for en-US", () => {
  assert.equal(formatMoney(123456, "USD", "en-US"), "$1,234.56");
});

test("formatMoney formats EUR for de-DE", () => {
  assert.equal(formatMoney(123456, "EUR", "de-DE"), "1.234,56 €");
});

test("formatMoney handles zero", () => {
  assert.equal(formatMoney(0, "USD", "en-US"), "$0.00");
});

test("formatMoney handles negative amounts", () => {
  assert.equal(formatMoney(-999, "USD", "en-US"), "-$9.99");
});

test("formatMoney rounds sub-cent input", () => {
  assert.equal(formatMoney(199.6, "USD", "en-US"), "$2.00");
});

test("formatCompact uses M for millions (en-US)", () => {
  assert.equal(formatCompact(1500000, "en-US"), "1.5M");
});

test("formatCompact uses Mio. for millions (de-DE)", () => {
  assert.match(formatCompact(1500000, "de-DE"), /1,5\s*Mio\.?/);
});

test("formatCompact uses K for thousands (en-US)", () => {
  assert.equal(formatCompact(4200, "en-US"), "4.2K");
});

test("formatCompact leaves small numbers alone", () => {
  assert.equal(formatCompact(999, "en-US"), "999");
});

test("timeAgo picks seconds for recent times (en-US)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 30_000, now, "en-US"), "30 seconds ago");
});

test("timeAgo picks minutes (en-US)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 5 * 60_000, now, "en-US"), "5 minutes ago");
});

test("timeAgo picks hours (de-DE)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 3 * 3600_000, now, "de-DE"), "vor 3 Stunden");
});

test("timeAgo picks days (en-US)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 3 * 86_400_000, now, "en-US"), "3 days ago");
});

test("timeAgo picks weeks (de-DE)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 14 * 86_400_000, now, "de-DE"), "vor 14 Tagen");
});

test("timeAgo picks months (en-US)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  const then = Date.parse("2023-10-01T12:00:00Z"); // ~92 days
  const out = timeAgo(then, now, "en-US");
  assert.match(out, /^3 months ago$/i);
});

test("timeAgo picks years for large spans (en-US)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now - 400 * 86_400_000, now, "en-US"), "1 year ago");
});

test("timeAgo handles future times (de-DE)", () => {
  const now = Date.parse("2024-01-01T12:00:00Z");
  assert.equal(timeAgo(now + 5 * 60_000, now, "de-DE"), "in 5 Minuten");
});
"})
